def shade(cell, fill):
    tcPr = cell._tc.get_or_add_tcPr()
    shd = tcPr.find(qn("w:shd")) or OxmlElement("w:shd")
    shd.set(qn("w:fill"), fill)
    if shd.getparent() is None: tcPr.append(shd)

def borders(cell, color=GRAY):
    tcPr = cell._tc.get_or_add_tcPr()
    bs = tcPr.first_child_found_in("w:tcBorders") or OxmlElement("w:tcBorders")
    if bs.getparent() is None: tcPr.append(bs)
    for e in ("top","left","bottom","right","insideH","insideV"):
        x = bs.find(qn("w:"+e)) or OxmlElement("w:"+e)
        x.set(qn("w:val"),"single"); x.set(qn("w:sz"),"6"); x.set(qn("w:space"),"0"); x.set(qn("w:color"),color)
        if x.getparent() is None: bs.append(x)

def margins(cell):
    tcPr = cell._tc.get_or_add_tcPr()
    m = tcPr.first_child_found_in("w:tcMar") or OxmlElement("w:tcMar")
    if m.getparent() is None: tcPr.append(m)
    for e in ("top","start","bottom","end"):
        x = m.find(qn("w:"+e)) or OxmlElement("w:"+e)
        x.set(qn("w:w"),"100"); x.set(qn("w:type"),"dxa")
        if x.getparent() is None: m.append(x)

def repeat_header(row):
    trPr = row._tr.get_or_add_trPr(); x=OxmlElement("w:tblHeader"); x.set(qn("w:val"),"true"); trPr.append(x)

def page_field(par):
    r=par.add_run(); a=OxmlElement("w:fldChar"); a.set(qn("w:fldCharType"),"begin")
    b=OxmlElement("w:instrText"); b.set(qn("xml:space"),"preserve"); b.text=" PAGE "
    c=OxmlElement("w:fldChar"); c.set(qn("w:fldCharType"),"end")
    r._r.extend([a,b,c])

def activity_image(path):
    im=Image.new("RGB",(1000,1250),"white"); d=ImageDraw.Draw(im)
    try: f=ImageFont.truetype("arial.ttf",22); fb=ImageFont.truetype("arialbd.ttf",28)
    except: f=fb=ImageFont.load_default()
    d.text((35,25),"RideShare: Booking Activity Diagram",fill=(31,78,121),font=fb)
    cx=500; ys=[100,210,320,450,590,730,870,1010,1150]
    labels=["Start","Enter dates and locations","Validate request","Calculate quote and check conflicts","Vehicle available?","Create pending booking","Payment enabled?","Notify owner and show status","End"]
    kinds=["round","box","box","box","diamond","box","diamond","box","round"]
    for y,lab,k in zip(ys,labels,kinds):
        if k=="round": d.ellipse((cx-38,y-38,cx+38,y+38),fill=(31,78,121))
        elif k=="diamond": d.polygon([(cx,y-42),(cx+180,y),(cx,y+42),(cx-180,y)],fill=(244,247,250),outline=(31,78,121),width=3)
        else: d.rounded_rectangle((cx-200,y-33,cx+200,y+33),radius=14,fill=(217,234,247),outline=(31,78,121),width=3)
        tw=d.textlength(lab,font=f); d.text((cx-tw/2,y-12),lab,fill="black",font=f)
    for y1,y2,k1,k2 in zip(ys,ys[1:],kinds,kinds[1:]):
        a=y1+(42 if k1=="diamond" else 38); b=y2-(42 if k2=="diamond" else 38)
        d.line((cx,a,cx,b),fill=(80,80,80),width=3); d.polygon([(cx,b),(cx-8,b-14),(cx+8,b-14)],fill=(80,80,80))
    d.text((35,1210),"Validation and availability precede persistence; payment is conditional.",fill=(90,90,90),font=f)
    im.save(path)
