def par(text="",style="Normal",align=None,bold=False,italic=False):
    p=doc.add_paragraph(style=style)
    if text:
        r=p.add_run(text); r.bold=bold; r.italic=italic
    if align is not None: p.alignment=align
    return p
def h(text,level=1): return doc.add_paragraph(text,style="Heading "+str(level))
def pb(): doc.add_page_break()
def caption(text): par(text,"Caption",WD_ALIGN_PARAGRAPH.CENTER)
def fig(file,text,width=6.2):
    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    inline=p.add_run().add_picture(str(file),width=Inches(width))
    inline._inline.docPr.set("descr", text); inline._inline.docPr.set("title", text)
    caption(text)
def bullets(items):
    for x in items: par(x,"List Bullet")
def numbered(items):
    for x in items: par(x,"List Number")
def table(headers,rows,widths=None,size=8.7):
    t=doc.add_table(rows=1,cols=len(headers)); t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.style="Table Grid"; repeat_header(t.rows[0])
    for i,x in enumerate(headers):
        c=t.rows[0].cells[i]; c.text=str(x); shade(c,NAVY); margins(c); borders(c); c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
        for p in c.paragraphs:
            p.alignment=WD_ALIGN_PARAGRAPH.CENTER
            for r in p.runs: r.font.name="Arial"; r.font.size=Pt(size); r.bold=True; r.font.color.rgb=RGBColor(255,255,255)
    for ri,row in enumerate(rows):
        cs=t.add_row().cells
        for i,x in enumerate(row):
            c=cs[i]; c.text=str(x); margins(c); borders(c); c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            if ri%2: shade(c,PALE)
            for p in c.paragraphs:
                for r in p.runs: r.font.name="Arial"; r.font.size=Pt(size)
    if widths:
        for row in t.rows:
            for i,w in enumerate(widths): row.cells[i].width=Inches(w)
    doc.add_paragraph()
    return t

