table(["Figure","Screen to capture","Minimum evidence"],[("Figure A.1","Public vehicle catalogue","Search, filter, vehicle cards, and availability indication."),("Figure A.2","Vehicle details and quote","Dates, locations, vehicle information, quote, deposit, and delivery option."),("Figure A.3","Owner vehicle management","Create or edit listing, media, rules, and availability state."),("Figure A.4","Booking dashboard","Booking status, owner or renter action, and notifications."),("Figure A.5","Map and tracking view","Pickup, destination, route preview, and live or simulated label."),("Figure A.6","Administrator dashboard","Member, vehicle verification, access request, or review moderation."),("Figure A.7","Invoice and review","Invoice details and post-rental review form or submitted review.")],[1.2,2.35,2.75],8.3); caption("Figure A.1 Screenshot capture checklist"); pb()
h("Appendix B – Additional Technical Details"); h("B.1 Representative Booking Algorithm",2)
numbered(["Authenticate the member and resolve the local application user.","Validate the vehicle identifier, date range, rental duration, location values, and selected delivery option.","Calculate the server-side quote from base price, rental duration, discounts, delivery fee, deposit, and additional rules.","Acquire a short booking lock or equivalent coordination control.","Query blocking bookings for the same vehicle and reject overlapping dates.","Create a pending or pending-payment booking with the calculated values and selected locations.","Create an owner notification and release the coordination lock in a finally-style cleanup path.","If payment is enabled, create and verify the provider order before confirming the booking."])
h("B.2 Representative API Resource Groups",2)
table(["Resource group","Representative responsibilities"],[("Authentication and access","Token verification, membership, access requests, member administration."),("Vehicles","Public browsing, nearby search, listing CRUD, uploads, availability, verification."),("Bookings","Quote, conflict checks, create, lifecycle transitions, coordination, cancellation."),("Payments","Orders, signature verification, provider state, refunds, extra charges, webhooks."),("Locations","Geocoding, reverse geocoding, routes, coordinate normalization, fallback behavior."),("Tracking","Session creation, protected updates, snapshots, event stream or polling fallback."),("Records","Notifications, reviews, invoices, pricing snapshots, recommendation conversations.")],[1.7,4.6],8.3)
h("B.3 Data Protection Considerations",2); bullets(["Store secrets in environment configuration and do not commit provider keys.","Return only fields needed by each public, member, owner, or administrator response.","Treat precise coordinates, phone numbers, identity identifiers, vehicle documents, payment identifiers, and recommendation conversations as sensitive.","Define retention and deletion rules for location updates, logs, invoices, and documents before production use.","Use HTTPS, secure token handling, rate limits, input validation, logging, backups, and least-privilege provider credentials.","Provide clear consent and visibility controls for location tracking and optional communications."]); pb()
h("Appendix C – Sample Outputs")
table(["Output","Sample value or state","Purpose"],[("Vehicle quote","Base rental amount + discount + delivery fee + security deposit","Shows server-calculated commercial terms before booking."),("Booking status","Pending → Approved → Active → Completed","Represents lifecycle progression under owner and renter actions."),("Payment status","Created → Verified → Captured or Refunded","Represents provider-backed payment state when enabled."),("Tracking status","Route preview; Live update; Simulated; Unavailable","Prevents confusing route estimates with verified GPS."),("Notification","Booking request received; booking approved; payment verified","Provides in-application operational communication."),("Invoice","Invoice number, booking, user, owner, amounts, issue date","Preserves a financial summary for the rental record."),("Recommendation","Suggested vehicle with matching preferences and explanation","Provides advisory assistance bounded by available vehicle data.")],[1.5,2.8,2.0],8.3); caption("Table C.1 Sample outputs")
